// Format the weekly report text for the gerente.
const r = ($input.first().json.report) || {};
const pl = r.pipeline || {};
const stages = ['new','contacted','qualified','visit_scheduled','offer'];
const labels = { new:'Nuevos', contacted:'Contactados', qualified:'Calificados', visit_scheduled:'Con visita', offer:'Con oferta' };
const plLines = stages.filter(s=>pl[s]).map(s=>`  \u2022 ${labels[s]}: ${pl[s]}`).join('\n') || '  (sin leads activos)';
const agents = r.agents || [];
const agLines = agents.length
  ? agents.map(a=>`  \u2022 ${a.name}: ${a.answered} resp, ${a.pending} pend, ${a.expired} sin responder`).join('\n')
  : '  (todos al d\u00eda)';
const text = [
  `\u{1F4CA} *Reporte semanal de seguimiento*`,
  ``,
  `*Pipeline activo:*`,
  plLines,
  ``,
  `*Esta semana:* ${r.visits_7d||0} visitas agendadas, ${r.won_7d||0} cerradas, ${r.lost_7d||0} perdidas`,
  ``,
  `*Respuesta de asesores:*`,
  agLines
].join('\n');
return [{ json: { text, t_nuevos: String(r.new_7d||0), t_won: String(r.won_7d||0), t_lost: String(r.lost_7d||0), t_visitas: String(r.visits_7d||0) } }];
